function ContainsDuplicate(nums: int[]) -> bool {
  let n = nums.length();
  let i = 0;
  while (i < n) {
    let j = i + 1;
    while (j < n) {
      if (nums[i] == nums[j]) {
        return true;
      }
      j += 1;
    }
    i += 1;
  }
  return false;
}

